	if (n <= 1) return n;
	return fib(n - 1) + fib(n - 2);
}
int main() {
	std::cout << fib(40) << std::endl;
	return 0;
}

output:
#include <iostream>
#include <vector>
long long fib(int n) {
	if (n <= 1) return n;
	std::vector<long long> dp(n + 1);
	dp[0] = 0; dp[1] = 1;
	for (int i = 2; i <= n; ++i) {
		dp[i] = dp[i - 1] + dp[i - 2];
	}
	return dp[n];
}
int main() {
	std::cout << fib(40) << std::endl;
	return 0;
}
---
The original recursive approach has exponential time complexity O(2^n) due to redundant recomputations of the same subproblems. The optimized version uses a DP table (std::vector) to achieve O(n) time complexity by storing and reusing previous results.

