int countWays(int amount, const std::vector<int>& coins) {
	if (amount == 0) return 1;
	if (amount < 0) return 0;
	int ways = 0;
	for (int coin : coins) {
		ways += countWays(amount - coin, coins);
	}
	return ways;
}
int main() {
	std::vector<int> c = {1, 2, 5};
	std::cout << countWays(10, c);
	return 0;
}

output:
#include <iostream>
#include <vector>
int countWays(int amount, const std::vector<int>& coins) {
	std::vector<int> dp(amount + 1, 0);
	dp[0] = 1;
	for (int coin : coins) {
		for (int i = coin; i <= amount; ++i) {
			dp[i] += dp[i - coin];
		}
	}
	return dp[amount];
}
int main() {
	std::vector<int> c = {1, 2, 5};
	std::cout << countWays(10, c);
	return 0;
}
---
The recursive solution suffers from overlapping subproblems, leading to a massive state space tree. The iterative DP approach reduces the complexity to O(amount * coins.size()) by filling a 1D table and ensuring each state is computed exactly once.

