output:
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
int lcs(std::string s1, std::string s2) {
	int m = s1.size();
	int n = s2.size();
	std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));
	for (int i = 1; i <= m; ++i) {
		for (int j = 1; j <= n; ++j) {
			if (s1[i-1] == s2[j-1]) dp[i][j] = 1 + dp[i-1][j-1];
			else dp[i][j] = std::max(dp[i-1][j], dp[i][j-1]);
		}
	}
	return dp[m][n];
}
int main() {
	std::cout << lcs("AGGTAB", "GXTXAYB");
	return 0;
}
---
The recursive implementation has O(2^n) complexity because it explores all possible subsequences repeatedly. Using a 2D DP table optimizes the time complexity to O(m * n) by memoizing results for each character pair index.

