#include <iostream>
#include <vector>
#include <algorithm>
int knapsack(int W, const std::vector<int>& wt, const std::vector<int>& val, int n) {
	if (n == 0 || W == 0) return 0;
	if (wt[n-1] > W) return knapsack(W, wt, val, n-1);
	return std::max(val[n-1] + knapsack(W - wt[n-1], wt, val, n-1), knapsack(W, wt, val, n-1));
}
int main() {
	std::vector<int> v = {60, 100, 120}, w = {10, 20, 30};
	std::cout << knapsack(50, w, v, 3);
	return 0;
}

output:
#include <iostream>
#include <vector>
#include <algorithm>
int knapsack(int W, const std::vector<int>& wt, const std::vector<int>& val) {
	int n = wt.size();
	std::vector<int> dp(W + 1, 0);
	for (int i = 0; i < n; i++) {
		for (int w = W; w >= wt[i]; w--) {
			dp[w] = std::max(dp[w], val[i] + dp[w - wt[i]]);
		}
	}
	return dp[W];
}
int main() {
	std::vector<int> v = {60, 100, 120}, w = {10, 20, 30};
	std::cout << knapsack(50, w, v);
	return 0;
}
---
The brute force recursion visits O(2^n) states, exceeding time limits for large inputs. The optimized version uses a 1D DP array to achieve O(n * W) time complexity and O(W) space, significantly improving cache locality and reducing memory overhead.

