output:
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
int findLCS(const std::string& A, const std::string& B) {
	int m = A.size(), n = B.size();
	std::vector<int> prev(n + 1, 0), curr(n + 1, 0);
	for (int i = 1; i <= m; i++) {
		for (int j = 1; j <= n; j++) {
			if (A[i-1] == B[j-1]) curr[j] = 1 + prev[j-1];
			else curr[j] = std::max(prev[j], curr[j-1]);
		}
		prev = curr;
	}
	return prev[n];
}
int main() {
	std::cout << findLCS("ABCDE", "ACE");
	return 0;
}
---
The original O(2^n) recursion is extremely slow for long strings. The optimized version uses O(m * n) time and O(n) space DP, reducing memory consumption compared to a full 2D table while maintaining linear-work efficiency per row.

