#include <iostream>
#include <vector>
#include <algorithm>
int ks(int i, int w, const std::vector<int>& weights, const std::vector<int>& values) {
	if (i < 0 || w <= 0) return 0;
	if (weights[i] > w) return ks(i-1, w, weights, values);
	return std::max(values[i] + ks(i-1, w - weights[i], weights, values), ks(i-1, w, weights, values));
}
int main() {
	std::vector<int> w = {2, 3, 4, 5}, v = {3, 4, 5, 6};
	std::cout << ks(3, 5, w, v);
	return 0;
}

output:
#include <iostream>
#include <vector>
#include <algorithm>
int ks(int capacity, const std::vector<int>& weights, const std::vector<int>& values) {
	int n = weights.size();
	std::vector<std::vector<int>> dp(n + 1, std::vector<int>(capacity + 1, 0));
	for (int i = 1; i <= n; i++) {
		for (int w = 1; w <= capacity; w++) {
			if (weights[i-1] <= w)
				dp[i][w] = std::max(values[i-1] + dp[i-1][w - weights[i-1]], dp[i-1][w]);
			else dp[i][w] = dp[i-1][w];
		}
	}
	return dp[n][capacity];
}
int main() {
	std::vector<int> w = {2, 3, 4, 5}, v = {3, 4, 5, 6};
	std::cout << ks(5, w, v);
	return 0;
}
---
By converting the exponential O(2^n) recursive calls into a 2D DP table, the complexity is reduced to O(n * capacity). This avoids redundant calculations of the same index-weight combinations.

