#include <iostream>
#include <vector>
#include <algorithm>
int minCoins(const std::vector<int>& coins, int amount) {
	std::vector<int> dp(amount + 1, amount + 1);
	dp[0] = 0;
	for (int i = 1; i <= amount; i++) {
		for (int c : coins) {
			if (i >= c) dp[i] = std::min(dp[i], 1 + dp[i-c]);
		}
	}
	return dp[amount] > amount ? -1 : dp[amount];
}
int main() {
	std::cout << minCoins({1, 2, 5}, 11);
	return 0;
}
