input:
#include <iostream>
#include <vector>
#include <algorithm>

int solve_knap(int cap, const std::vector<int>& w, const std::vector<int>& v, int n) {
	if (n == 0 || cap == 0) return 0;
	if (w[n-1] > cap) return solve_knap(cap, w, v, n-1);
	return std::max(v[n-1] + solve_knap(cap - w[n-1], w, v, n-1), solve_knap(cap, w, v, n-1));
}

int main() {
	std::vector<int> values = {60, 100, 120}, weights = {10, 20, 30};
	std::cout << solve_knap(50, weights, values, 3) << std::endl;
	return 0;
}

output:
#include <iostream>
#include <vector>
#include <algorithm>

int knap_optimized(int capacity, const std::vector<int>& weights, const std::vector<int>& values) {
	int n = values.size();
	std::vector<int> dp(capacity + 1, 0);
	for (int i = 0; i < n; ++i) {
		for (int w = capacity; w >= weights[i]; --w) {
			dp[w] = std::max(dp[w], values[i] + dp[w - weights[i]]);
		}
	}
	return dp[capacity];
}

int main() {
	std::vector<int> values = {60, 100, 120}, weights = {10, 20, 30};
	std::cout << knap_optimized(50, weights, values) << std::endl;
	return 0;
}
